-- December 2025 payroll seed for CodeAge Pvt. Ltd.
-- Import this after 2026_04_09_000011_employee_master_seed.sql.
SET NAMES utf8mb4;

-- Schema alignment for payroll fields and tables.
SET @schema_name := DATABASE();

SET @sql := IF(
  EXISTS(
    SELECT 1
    FROM `information_schema`.`COLUMNS`
    WHERE `TABLE_SCHEMA` = @schema_name
      AND `TABLE_NAME` = 'employees'
      AND `COLUMN_NAME` = 'payment_mode'
  ),
  'SELECT 1',
  'ALTER TABLE `employees` ADD COLUMN `payment_mode` varchar(255) NULL AFTER `payroll_status`'
);
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @sql := IF(
  EXISTS(
    SELECT 1
    FROM `information_schema`.`COLUMNS`
    WHERE `TABLE_SCHEMA` = @schema_name
      AND `TABLE_NAME` = 'employees'
      AND `COLUMN_NAME` = 'bank_code'
  ),
  'SELECT 1',
  'ALTER TABLE `employees` ADD COLUMN `bank_code` varchar(20) NULL AFTER `bank_name`'
);
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @sql := IF(
  EXISTS(
    SELECT 1
    FROM `information_schema`.`COLUMNS`
    WHERE `TABLE_SCHEMA` = @schema_name
      AND `TABLE_NAME` = 'employees'
      AND `COLUMN_NAME` = 'current_salary'
  ),
  'SELECT 1',
  'ALTER TABLE `employees` ADD COLUMN `current_salary` decimal(12,2) NULL AFTER `iban`'
);
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @sql := IF(
  EXISTS(
    SELECT 1
    FROM `information_schema`.`COLUMNS`
    WHERE `TABLE_SCHEMA` = @schema_name
      AND `TABLE_NAME` = 'employees'
      AND `COLUMN_NAME` = 'last_increment'
  ),
  'SELECT 1',
  'ALTER TABLE `employees` ADD COLUMN `last_increment` decimal(12,2) NULL AFTER `current_salary`'
);
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

CREATE TABLE IF NOT EXISTS `payroll_runs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `pay_period_month` date NOT NULL,
  `payment_date` date DEFAULT NULL,
  `email_subject` varchar(255) DEFAULT NULL,
  `email_body` text DEFAULT NULL,
  `source_workbook` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `payroll_runs_pay_period_month_unique` (`pay_period_month`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `employee_payroll_records` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `payroll_run_id` bigint(20) unsigned NOT NULL,
  `employee_id` bigint(20) unsigned NOT NULL,
  `bank_code` varchar(20) DEFAULT NULL,
  `beneficiary_name` varchar(255) DEFAULT NULL,
  `beneficiary_account_no` varchar(255) DEFAULT NULL,
  `contact_number` varchar(255) DEFAULT NULL,
  `email_address` varchar(255) DEFAULT NULL,
  `days_absent` int unsigned NOT NULL DEFAULT 0,
  `short_hours_days` int unsigned NOT NULL DEFAULT 0,
  `basic_salary` decimal(12,2) NOT NULL DEFAULT 0.00,
  `last_increment` decimal(12,2) NOT NULL DEFAULT 0.00,
  `incentives_bonus` decimal(12,2) NOT NULL DEFAULT 0.00,
  `punctuality_bonus` decimal(12,2) NOT NULL DEFAULT 0.00,
  `positive_arrears` decimal(12,2) NOT NULL DEFAULT 0.00,
  `positive_other` decimal(12,2) NOT NULL DEFAULT 0.00,
  `security_deduction` decimal(12,2) NOT NULL DEFAULT 0.00,
  `non_paid_leave_deduction` decimal(12,2) NOT NULL DEFAULT 0.00,
  `attendance_penalty` decimal(12,2) NOT NULL DEFAULT 0.00,
  `arrears_deduction` decimal(12,2) NOT NULL DEFAULT 0.00,
  `other_deduction` decimal(12,2) NOT NULL DEFAULT 0.00,
  `gross_salary` decimal(12,2) NOT NULL DEFAULT 0.00,
  `income_tax` decimal(12,2) NOT NULL DEFAULT 0.00,
  `net_salary` decimal(12,2) NOT NULL DEFAULT 0.00,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `employee_payroll_records_payroll_run_id_employee_id_unique` (`payroll_run_id`, `employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `employee_security_fund_snapshots` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint(20) unsigned NOT NULL,
  `fiscal_year_label` varchar(20) NOT NULL,
  `snapshot_month` date NOT NULL,
  `opening_arrears` decimal(12,2) NOT NULL DEFAULT 0.00,
  `july_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `august_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `september_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `october_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `november_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `december_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `january_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `february_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `march_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `april_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `may_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `june_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `paid_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `balance_in_account` decimal(12,2) NOT NULL DEFAULT 0.00,
  `remarks` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `security_snapshot_unique` (`employee_id`, `fiscal_year_label`, `snapshot_month`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Migration bookkeeping.
SET @next_batch := (SELECT IFNULL(MAX(`batch`), 0) + 1 FROM `migrations`);
INSERT IGNORE INTO `migrations` (`migration`, `batch`) VALUES
('2026_04_09_000011_add_payroll_fields_to_employees_table', @next_batch),
('2026_04_09_000012_create_payroll_runs_table', @next_batch),
('2026_04_09_000013_create_employee_payroll_records_table', @next_batch),
('2026_04_09_000014_create_employee_security_fund_snapshots_table', @next_batch);

